public boolean compatibleWithBlock(TFMLogicBlock _block)
{
    TFMLogicBlockDataCollectionInterface    collectBlock;
    TFMRegistrationCollector                quantity;
    if ( _block is TFMLogicBlockDataCollectionInterface)
    {
        collectBlock = _block as TFMLogicBlockDataCollectionInterface;
        quantity = collectBlock.registrationCollectors().getCollector(TFMConstants::Quantity());

        return quantity!= null;
    }
    return false;
}

public void modifyRequestBeforePost(TFMRequestElement _request)
{        
    TFMRequestItemAndDimensionElement docRequest = _request.convertToOtherRequestType(classStr(TFMRequestItemAndDimensionElement));
    Qty         qty = docRequest.parmQuantity();
    if (!qty)
    {
        return;
    }

    if (qty > 0)
    {
        qty = qty*-1;
    }

    _request.addField(MobConstants::Quantity(), strFmt('%1',qty), true);

}

